from nlib import *
S=[]
def C(id,title,sc,sm,b,d,e,f,dy,made,sec,kn=("cell_types",),par=(),rel=(),mol=None,cert="C1",oq=None,bk="ANP",proc=()):
    S.append(N(id,title,"cell","cell",sc,sm,b,d,e,f,dy,par=par,made=made,proc=proc,refs=[(bk,sec)],kn=kn,rel=rel,mol=mol,cert=cert,oq=oq))
BASE=["nucleus","mitochondrion","ribosome","endoplasmic_reticulum","golgi_apparatus","cell_membrane","cytoskeleton"]
C("neuron","Neuron",1e-4,"A nerve cell that sends electrical and chemical signals.","Neurons collect signals with branches (dendrites), decide whether to fire, and send pulses along a long fiber (axon).","The soma holds the nucleus; the axon may be wrapped in insulating myelin; synapses at the tips release neurotransmitters.","Resting potential ≈ -70 mV; action potential via voltage-gated Na+/K+ channels; axon lengths up to ≈ 1 m; ≈ 10^3-10^4 synapses per cortical neuron.",[("Soma","≈ 4-100 µm"),("Resting potential","≈ -70 mV"),("Synapses","≈ 10^3-10^4")],"Some neurons in your leg are about a meter long, the longest cells in the body.",["nucleus","mitochondrion","endoplasmic_reticulum","golgi_apparatus","ribosome","cell_membrane","cytoskeleton"],"12.2",kn=("action_potential","synapse_plasticity"),mol=["acetylcholine","dopamine","gaba","serotonin"],proc=["action_potential","synaptic_transmission"])
C("astrocyte","Astrocyte",5e-5,"A star-shaped glial cell that supports neurons.","Astrocytes feed neurons, tidy up chemicals, and help form the blood-brain barrier.","They wrap synapses and regulate extracellular K+ and glutamate.","Express GFAP, AQP4 at endfeet; take up glutamate via EAAT1/2; contribute to the glymphatic system; ≈ 1:1 with neurons overall.",[("Size","≈ 50 µm"),("Synapses contacted","up to ≈ 2×10^6 (human)")],"A single human astrocyte can touch around two million synapses.",BASE,"12.2",kn=("brain_organization",),proc=["synaptic_transmission"])
C("red_blood_cell","Red blood cell (erythrocyte)",7.5e-6,"A disc-shaped cell packed with hemoglobin to carry oxygen.","Red blood cells carry oxygen from lungs to tissues. They have no nucleus, so there's more room for hemoglobin.","Their biconcave shape gives a large surface and flexibility to squeeze through capillaries. They live ≈ 120 days.","≈ 270 million hemoglobin molecules per cell; glycolysis only (no mitochondria); spectrin-actin skeleton; removed by splenic macrophages; ≈ 2×10^6 made per second.",[("Diameter","≈ 7.5 µm"),("Lifespan","≈ 120 days"),("Hemoglobin per cell","≈ 2.7×10^8 molecules")],"Each second your marrow releases about two million new red blood cells.",["cell_membrane","cytoskeleton"],"18.3",kn=("heme_oxygen","blood_circulation"),mol=["4hhb","heme_b","oxygen","carbon_dioxide"],proc=["breathing"])
C("neutrophil","Neutrophil",1.2e-5,"The most common white blood cell and a first responder to bacteria.","Neutrophils race to infections and engulf germs.","They live only hours to days. Pus is largely dead neutrophils.","Multilobed nucleus; granules with myeloperoxidase; NETosis; chemotaxis toward IL-8 and fMLP; ≈ 50-70% of leukocytes.",[("Diameter","≈ 12 µm"),("Share of WBC","≈ 50-70%"),("Lifespan","≈ hours-days")],"You make about 100 billion neutrophils each day.",BASE[:-2]+["lysosome","cell_membrane","cytoskeleton"],"18.4",kn=("immune_system",),proc=["immune_response"],bk="ANP")
C("macrophage","Macrophage",2e-5,"A large cell that swallows microbes and debris and alerts other immune cells.","Macrophages are the clean-up crew and sentries of the immune system.","They engulf (phagocytose) germs and display fragments to T cells.","Differentiate from monocytes or arise from embryonic precursors (tissue-resident); polarization states (M1/M2 simplification); express TLRs and scavenger receptors.",[("Diameter","≈ 20 µm"),("Lifespan","≈ months")],"Specialized macrophages exist in many organs: Kupffer cells in the liver, microglia in the brain.",BASE+["lysosome"],"21.2",kn=("immune_system",),proc=["immune_response"])
C("lymphocyte_t","T lymphocyte (T cell)",8e-6,"A white cell that coordinates or carries out targeted attacks.","T cells recognize specific invaders, and some kill infected cells directly.","They mature in the thymus. Helper T cells coordinate; cytotoxic T cells kill; memory T cells remember.","TCR recognizes peptide-MHC; CD4+ helper vs CD8+ cytotoxic; costimulation via CD28; regulatory T cells maintain tolerance; repertoire ≈ 10^15-10^18 potential TCRs.",[("Diameter","≈ 8 µm"),("Potential receptor types","≈ 10^15+")],"The potential diversity of T-cell receptors exceeds the number of cells you own by far.",["nucleus","mitochondrion","ribosome","cell_membrane","cytoskeleton"],"21.3",kn=("immune_system",),proc=["immune_response"])
C("lymphocyte_b","B lymphocyte (B cell)",8e-6,"A white cell that becomes an antibody-producing factory.","When a B cell recognizes a germ, it multiplies and its descendants release antibodies.","Memory B cells make later responses faster and stronger.","BCR diversity from V(D)J recombination; somatic hypermutation and class switching in germinal centers; plasma cells secrete ≈ 2,000 antibodies per second.",[("Diameter","≈ 8 µm"),("Antibody secretion","≈ 2,000/s per plasma cell")],"A single plasma cell is one of the most prolific protein-secreting cells in the body.",["nucleus","mitochondrion","ribosome","endoplasmic_reticulum","golgi_apparatus","cell_membrane"],"21.4",kn=("immune_system",),proc=["immune_response"])
C("platelet","Platelet (thrombocyte)",3e-6,"A cell fragment that plugs breaks in blood vessels.","Platelets stick to wounds and to each other to form a plug and start a clot.","They are pieces of giant marrow cells (megakaryocytes) and last about a week.","Activated via collagen/GPVI and thrombin; α- and dense granules; integrin αIIbβ3 binds fibrinogen; ≈ 150-400×10^9/L.",[("Diameter","≈ 2-3 µm"),("Lifespan","≈ 7-10 days")],"Platelets have no nucleus, they are fragments of larger cells.",["cell_membrane","cytoskeleton","mitochondrion"],"18.4",kn=("blood_circulation",),proc=["blood_clotting"])
C("cardiomyocyte","Cardiomyocyte (heart muscle cell)",1e-4,"The striated, branching muscle cell of the heart.","Heart cells contract in unison to pump blood.","They are rich in mitochondria and linked end to end by intercalated discs.","Ca2+-induced Ca2+ release via L-type channels and ryanodine receptors; T-tubules; one or two nuclei; limited regeneration (≈ 0.5-1%/yr).",[("Length","≈ 100 µm"),("Mitochondria","≈ 30-35% of volume")],"Your heart muscle cells are mostly the ones you were born with.",["nucleus","mitochondrion","sarcomere","cell_membrane","endoplasmic_reticulum"],"19.2",kn=("muscle_contraction",),mol=["atp","creatine"],proc=["cardiac_cycle","muscle_contraction"])
C("skeletal_muscle_fiber","Skeletal muscle fiber",5e-5,"A long multi-nucleated cell packed with contractile units.","A muscle fiber is a single giant cell that shortens when stimulated.","Formed by fusion of many precursor cells, it has hundreds of nuclei lined along the edge.","Contains myofibrils of repeating sarcomeres; T-tubule/SR triads; fiber types I, IIa, IIx; satellite cells enable regeneration.",[("Diameter","≈ 50-100 µm"),("Length","up to ≈ 30 cm")],"A single muscle fiber can be as long as a ruler.",["nucleus","mitochondrion","sarcomere","cell_membrane","endoplasmic_reticulum"],"10.2",kn=("muscle_contraction",),mol=["atp","creatine"],proc=["muscle_contraction"])
C("smooth_muscle_cell","Smooth muscle cell",1e-4,"A spindle-shaped cell that contracts slowly and steadily.","These cells squeeze vessels and organs without conscious control.","They are not striped and use actin and myosin arranged more loosely.","Ca2+-calmodulin MLCK phosphorylates myosin light chain; caveolae; dense bodies anchor filaments; capable of proliferation and phenotypic switching.",[("Length","≈ 30-200 µm")],"They can maintain tension for hours at very low energy cost.",["nucleus","mitochondrion","cytoskeleton","cell_membrane"],"10.8",kn=("muscle_contraction",),proc=["muscle_contraction"])
C("hepatocyte","Hepatocyte (liver cell)",3e-5,"The main liver cell, a versatile chemical worker.","Hepatocytes process nutrients, make proteins and bile, and neutralize toxins.","They make up about 80% of liver cells and have lots of mitochondria and smooth ER.","Express CYP450 enzymes, albumin, clotting factors; glycogen storage; polyploid (often tetraploid); can re-enter the cell cycle after injury.",[("Diameter","≈ 25-30 µm"),("Mitochondria","≈ 1,000-2,000 per cell")],"Hepatocytes live about 200-300 days and are among the few cells in adults that can regrow organs.",BASE+["lysosome","peroxisome"],"23.6",kn=("digestion_renal",),mol=["glucose_alpha","urea"],proc=["digestion"])
C("enterocyte","Enterocyte (intestinal absorptive cell)",2e-5,"A tall absorbing cell lining the intestine.","Enterocytes pick up nutrients from digested food.","Their top surface bristles with microvilli, forming the brush border.","Express SGLT1, GLUT5, peptide transporters; tight junctions; renewed every ≈ 3-5 days from crypt stem cells.",[("Height","≈ 20-25 µm"),("Microvilli per cell","≈ 3,000")],"Each enterocyte has about 3,000 microvilli.",BASE+["lysosome"],"23.5",kn=("digestion_renal",),proc=["digestion"])
C("osteocyte","Osteocyte",2e-5,"A mature bone cell living inside the bone it built.","Osteocytes are trapped in tiny pockets inside bone and sense strain.","They talk to each other through thin channels.","Dendritic network in canaliculi; secrete sclerostin and FGF23; ≈ 90-95% of bone cells; lifespan of decades.",[("Share of bone cells","≈ 90-95%"),("Lifespan","up to decades")],"Osteocytes are the longest-lived bone cells, living for decades.",["nucleus","mitochondrion","cell_membrane","cytoskeleton"],"6.3",kn=("musculoskeletal",),proc=["bone_remodeling"])
C("osteoblast","Osteoblast",2e-5,"A cell that builds new bone.","Osteoblasts lay down the collagen frame of bone and then mineralize it.","They come from stem cells in marrow and periosteum.","Secrete osteoid (type I collagen), alkaline phosphatase; signal to osteoclasts through RANKL/OPG; some become osteocytes.",[("Size","≈ 20-30 µm")],"Many osteoblasts end up buried in the bone they make and become osteocytes.",BASE,"6.3",kn=("musculoskeletal",),proc=["bone_remodeling"])
C("osteoclast","Osteoclast",1e-4,"A large cell that dissolves old bone.","Osteoclasts break down bone so it can be renewed and calcium released.","They form from fused blood-cell precursors.","Multinucleated; ruffled border; secrete H+ and cathepsin K; RANKL-dependent differentiation.",[("Nuclei","≈ 3-20"),("Size","≈ 100 µm")],"Together with osteoblasts they renew the whole skeleton about every ten years.",["nucleus","mitochondrion","lysosome","cell_membrane","cytoskeleton"],"6.4",kn=("musculoskeletal",),proc=["bone_remodeling"])
C("chondrocyte","Chondrocyte",1.5e-5,"The cartilage cell, living in tiny cavities of its own matrix.","Chondrocytes make and maintain cartilage.","They live in lacunae and get nutrients by diffusion because cartilage has no vessels.","Produce collagen II and aggrecan; hypoxic metabolism; hypertrophy in growth plates leading to ossification.",[("Size","≈ 10-30 µm")],"Cartilage heals poorly partly because chondrocytes are few and isolated.",BASE,"4.3",kn=("musculoskeletal",))
C("keratinocyte","Keratinocyte",2e-5,"The main skin cell, which fills with tough keratin protein.","Keratinocytes are made deep in the epidermis, rise to the surface, flatten and die as a waterproof shield.","They take about 4 weeks to travel from bottom to top.","Differentiation: basal (K5/K14) to spinous (K1/K10) to granular (filaggrin, loricrin) to cornified envelope; desmosomal adhesion.",[("Share of epidermal cells","≈ 90%"),("Travel time","≈ 28-40 days")],"Your outermost skin cells are dead keratin-filled flakes.",["nucleus","mitochondrion","cytoskeleton","cell_membrane"],"5.1",kn=("skin_integument",))
C("adipocyte","Adipocyte (fat cell)",1e-4,"A cell storing energy as a large fat droplet.","Fat cells are mostly one huge oil droplet that pushes everything else to the edge.","They also release hormones like leptin.","Unilocular lipid droplet ≈ 90% of volume; lipolysis via HSL/ATGL; number set largely by adolescence, with ≈ 10%/yr turnover.",[("Diameter","≈ 70-120 µm"),("Turnover","≈ 10%/yr")],"The number of fat cells is largely fixed by adulthood; cells change size more than number.",["nucleus","mitochondrion","cell_membrane","endoplasmic_reticulum"],"4.3",kn=("metabolism_overview",),mol=["tripalmitin","oleic_acid"])
C("fibroblast","Fibroblast",3e-5,"The cell that builds the connective-tissue fibers.","Fibroblasts make collagen and repair wounds.","They help form scars.","Activated to myofibroblasts in wound healing; collagen I/III synthesis; ECM remodeling by MMPs.",[("Length","≈ 30-100 µm")],"Scars are essentially dense collagen made by fibroblasts.",BASE,"4.3",kn=("cell_types",))
C("rod_cell","Rod photoreceptor",5e-6,"A retinal cell specialized for dim light.","Rods let you see at night, but only in shades of gray.","They contain a light-catching pigment (rhodopsin) stacked in discs.","≈ 1.2×10^8 per eye; single-photon sensitivity; rhodopsin with 11-cis-retinal; phototransduction via transducin-PDE6 cascade; hyperpolarizes in light.",[("Number","≈ 1.2×10^8 per eye"),("Length","≈ 50-60 µm")],"A dark-adapted rod can respond to a single photon.",["nucleus","mitochondrion","cell_membrane","ribosome"],"14.1",kn=("vision_eye",),mol=["retinal"],proc=["vision"])
C("cone_cell","Cone photoreceptor",5e-6,"A retinal cell for color and sharp daylight vision.","Cones detect color and fine detail in bright light.","Three kinds respond best to short, medium or long (blue, green, red) wavelengths.","≈ 6×10^6 per eye, concentrated at the fovea; S, M, L opsins; faster, less sensitive than rods.",[("Number","≈ 6×10^6 per eye"),("Types","3 (S, M, L)")],"Many people with color-vision deficiency lack one of the three cone pigments or have a shifted one.",["nucleus","mitochondrion","cell_membrane","ribosome"],"14.1",kn=("vision_eye",),mol=["retinal"],proc=["vision"])
C("sperm","Sperm cell",5e-5,"The male gamete, a tiny swimming cell carrying half a set of chromosomes.","A sperm swims with a whip-like tail to reach an egg.","It carries 23 chromosomes and little else beyond energy machinery.","Head with nucleus and acrosome, midpiece packed with mitochondria, flagellum; ≈ 45-60 µm long; ≈ 15-200×10^6 per mL.",[("Length","≈ 50 µm"),("Chromosomes","23")],"Sperm cells are among the smallest human cells but must travel a long way relative to their size.",["nucleus","mitochondrion","cell_membrane","cytoskeleton"],"27.1",kn=("development_biology",))
C("egg_cell","Egg cell (oocyte)",1.2e-4,"The female gamete, the largest human cell.","The egg carries half the genetic instructions and nutrients that start a new person.","It is surrounded by a protective coat and cells.","Arrested in prophase I (primary oocyte) until ovulation and in metaphase II until fertilization; zona pellucida; ≈ 120 µm.",[("Diameter","≈ 0.1-0.12 mm"),("Chromosomes","23 after meiosis")],"It is just visible to the naked eye.",["nucleus","mitochondrion","cell_membrane","endoplasmic_reticulum","golgi_apparatus"],"27.2",kn=("development_biology",))
C("stem_cell","Hematopoietic stem cell",1e-5,"A cell that can renew itself and produce all blood cell types.","Stem cells in your marrow are the source of every blood cell.","They divide rarely to protect their DNA.","Defined by CD34+ CD38- markers; niches in marrow; transplant therapy; clonal hematopoiesis rises with age.",[("Frequency","≈ 1 in 10^4-10^5 marrow cells"),("Divisions","few per year")],"Your blood system descends from only a few tens of thousands of active stem cells.",["nucleus","mitochondrion","cell_membrane"],"18.2",kn=("cell_types","development_biology"),cert="C2",oq=["How do stem-cell niches regulate self-renewal versus differentiation in aging?"])
C("melanocyte","Melanocyte",1.5e-5,"A skin cell making the pigment melanin.","Melanocytes shade your skin against UV light.","They pass pigment packages to neighbouring cells.","Melanosomes with eumelanin/pheomelanin transferred to ≈ 36 keratinocytes each; density roughly similar across skin tones.",[("Pigment","melanin")],"People of all skin tones have roughly the same number of melanocytes; they differ in how much pigment is made.",BASE[:4]+["cell_membrane"],"5.1",kn=("skin_integument",))
C("beta_cell","Pancreatic beta cell",1.5e-5,"The insulin-secreting cell of the pancreas.","Beta cells sense blood sugar and release insulin.","They store insulin in granules ready to release.","Glucose uptake via GLUT, glucokinase, ATP-sensitive K+ channels close, depolarization, Ca2+ influx, insulin exocytosis (biphasic).",[("Diameter","≈ 15 µm"),("Product","insulin")],"Beta cells sit in islets and work like glucose sensors.",BASE+["golgi_apparatus"],"17.9",kn=("endocrine_physiology",),proc=["hormone_signaling"])
save("body_cells",S)
